    PING_STABLE_MS: 30000,         // Stable ping interval (after convergence)
    PING_STABLE_AFTER: 5,          // Pongs before switching to stable interval
    HOME_REFRESH_MS: 5000,        // Home watch parties refresh (increased from 2s)
